import{_ as r,o as t,c as n,ae as a}from"./chunks/framework.Cqu5Y2mC.js";const b=JSON.parse('{"title":"Protokoll Sitzung 06","description":"","frontmatter":{},"headers":[],"relativePath":"05-Gemeinsam/2026-04-24-Protokoll.md","filePath":"05-Gemeinsam/2026-04-24-Protokoll.md"}'),i={name:"05-Gemeinsam/2026-04-24-Protokoll.md"};function l(o,e,s,u,d,g){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="protokoll-sitzung-06" tabindex="-1">Protokoll Sitzung 06 <a class="header-anchor" href="#protokoll-sitzung-06" aria-label="Permalink to &quot;Protokoll Sitzung 06&quot;">​</a></h1><p><strong>Datum:</strong> <em><strong>2026-04-24</strong></em><br><strong>Sitzung:</strong> <em><strong>06</strong></em><br><strong>Protokollführer:</strong> <em><strong>Sofia Jäger; Daniel Saracoglu</strong></em></p><p><strong>Teilnehmer:</strong><br><strong>Sybit:</strong> <em><strong>Stephan Strittmatter</strong></em><br><strong>Lehrer:</strong> <em><strong>Stefan Martin, Karl Laber</strong></em><br><strong>Schüler:</strong><br><em><strong>01-Betrieb: Artem, Huzaifa, Irakli, Marius</strong></em><br><em><strong>02-Hardware: Eray, Lukas, Marlon</strong></em><br><em><strong>03-Software: Felix, Jannick, Theodor</strong></em><br><em><strong>04-Projektleitung: Daniel, Jan, Sofia</strong></em></p><hr><h2 id="aktueller-stand-ruckblick-seit-der-letzten-sitzung" tabindex="-1">Aktueller Stand/ Rückblick seit der letzten Sitzung: <a class="header-anchor" href="#aktueller-stand-ruckblick-seit-der-letzten-sitzung" aria-label="Permalink to &quot;Aktueller Stand/ Rückblick seit der letzten Sitzung:&quot;">​</a></h2><h3 id="_1-betrieb" tabindex="-1">1. Betrieb: <a class="header-anchor" href="#_1-betrieb" aria-label="Permalink to &quot;1. Betrieb:&quot;">​</a></h3><ul><li>Anpassungen Infrastruktur</li><li>Sichere Verbindungsstrategie definiert</li><li>Apollonsensorim Gateway erfolgreich registriert</li><li>Entscheidung, einen Tunnel statt einem Webserver mit NGINX zuverwenden, um den Zugriff und die Kommunikation zu steuern</li><li>Tunnel ist noch nicht eingerichtet und wird noch durch https mit Benutzername und Passwort realisiert</li></ul><h3 id="_2-hardware" tabindex="-1">2. Hardware: <a class="header-anchor" href="#_2-hardware" aria-label="Permalink to &quot;2. Hardware:&quot;">​</a></h3><ul><li>Marlon hat das CAD-Modell für die Halterung des Sensors optimiert und ein fertiges Modell gedruckt</li><li>Es wird eine stärkere Antenne benötigt</li><li>Das Gateway wurde so verändert, dass es jetzt Daten empfangen kann</li></ul><h3 id="_3-software" tabindex="-1">3. Software: <a class="header-anchor" href="#_3-software" aria-label="Permalink to &quot;3. Software:&quot;">​</a></h3><ul><li>Simulator und Backend auf MQTT umgestellt</li><li>Simulator und Backend an die echten Sensordaten angepasst</li><li>Dekodierer in Backend für Sensordaten eingebaut</li></ul><h3 id="_4-projektleitung" tabindex="-1">4. Projektleitung: <a class="header-anchor" href="#_4-projektleitung" aria-label="Permalink to &quot;4. Projektleitung:&quot;">​</a></h3><ul><li>Wir haben einen endgülitgen Termin für das nächste Meeting vereinbart und bekanntgegeben (12.06.2026)</li></ul><hr><h2 id="ziele-bis-zur-nachsten-sitzung" tabindex="-1">Ziele bis zur nächsten Sitzung: <a class="header-anchor" href="#ziele-bis-zur-nachsten-sitzung" aria-label="Permalink to &quot;Ziele bis zur nächsten Sitzung:&quot;">​</a></h2><h3 id="_1-betrieb-1" tabindex="-1">1. Betrieb: <a class="header-anchor" href="#_1-betrieb-1" aria-label="Permalink to &quot;1. Betrieb:&quot;">​</a></h3><ul><li>ssh Zugang base station einloggen</li><li>Zugriff per Konsole auf das Gateway herstellen</li><li>Hilfe benötigt um sich in Secure Shell (ssh) einzuloggen und das Passwort ändern zu können (Ursprungspasswort stimmt nicht)</li></ul><h3 id="_2-hardware-1" tabindex="-1">2. Hardware: <a class="header-anchor" href="#_2-hardware-1" aria-label="Permalink to &quot;2. Hardware:&quot;">​</a></h3><ul><li>Es wurden Klebestreifen an der Halterung befestigt um die Halterung im Mülleimer zu befestigen =&gt; Resultat: Hält nicht, Sensor ist in Mülleimer gefallen</li><li>Warten auf die neue Antenne</li></ul><h3 id="_3-software-1" tabindex="-1">3. Software: <a class="header-anchor" href="#_3-software-1" aria-label="Permalink to &quot;3. Software:&quot;">​</a></h3><ul><li>Tests durchführen sodass alle neuen Änderungen überprüft werden, ob es funktioniert</li></ul><h3 id="_4-projektleitung-1" tabindex="-1">4. Projektleitung: <a class="header-anchor" href="#_4-projektleitung-1" aria-label="Permalink to &quot;4. Projektleitung:&quot;">​</a></h3><ul><li>Abhängig von Frau Bielers Antwort eventuell Nuudel Umfrage erstellen.</li><li>Angebot von Herr Bucher für die zwei Basisstationen und die zwei Antennen einholen.</li><li>E-Mail für Betrieb senden, um Frage zu klären</li></ul>',23)])])}const m=r(i,[["render",l]]);export{b as __pageData,m as default};
